mapper.sql:
AND schedule.queue_kind = #{queueKind}
AND schedule.status IN

    #{status}

AND (
    (#{queueKind} != 'publish_result_check'
        AND (schedule.next_attempt_at IS NULL OR schedule.next_attempt_at <= #{now}))
    OR (#{queueKind} = 'publish_result_check' AND (
        schedule.next_attempt_at <= #{now}
        OR (schedule.next_attempt_at IS NULL
            AND schedule.status IN ('publish_due', 'published_url_pending', 'publish_unknown'))
        OR (schedule.next_attempt_at IS NULL
            AND schedule.status = 'scheduled'
            AND COALESCE(schedule.platform_scheduled_at, schedule.planned_publish_at) <= #{now})
    ))
)
AND (schedule.locked_until IS NULL OR schedule.locked_until < #{now})

AND environment.status = 'active'
AND environment.deleted_at IS NULL
AND agent_binding.status = 'active'
AND agent_binding.bound_by = #{operatorId}
AND helper_runtime.operator_id = #{operatorId}
AND helper_session.operator_id = #{operatorId}
AND helper_session.status = 'active'
AND helper_session.expires_at > #{now}
AND (
    helper_session.brand_id IS NULL
    OR helper_session.brand_id = environment.brand_id
)

mapper.select:
SELECT COUNT(DISTINCT schedule.id) FROM self_media_publish_schedule schedule JOIN browser_environment environment ON environment.id = schedule.browser_environment_id AND environment.brand_id = schedule.brand_id JOIN browser_environment_agent_binding agent_binding ON agent_binding.browser_environment_id = environment.id JOIN local_agent_runtime_status helper_runtime ON helper_runtime.machine_id = agent_binding.machine_id AND helper_runtime.active_profile = agent_binding.active_profile AND helper_runtime.session_id = #{localAgentSessionId} JOIN local_agent_session helper_session ON helper_session.id = helper_runtime.session_id WHERE schedule.status IN
#{status}
AND schedule.locked_until IS NOT NULL AND schedule.locked_until > #{now}

mapper.update:
UPDATE self_media_publish_schedule SET locked_until = #{lockedUntil}, updated_at = #{now} WHERE id = #{scheduleId} AND runtime_worker_id = #{runtimeWorkerId} AND status IN
#{status}
AND EXISTS ( SELECT 1 FROM browser_environment environment JOIN browser_environment_agent_binding agent_binding ON agent_binding.browser_environment_id = environment.id JOIN local_agent_runtime_status helper_runtime ON helper_runtime.machine_id = agent_binding.machine_id AND helper_runtime.active_profile = agent_binding.active_profile AND helper_runtime.session_id = #{localAgentSessionId} JOIN local_agent_session helper_session ON helper_session.id = helper_runtime.session_id WHERE environment.id = self_media_publish_schedule.browser_environment_id AND environment.brand_id = self_media_publish_schedule.brand_id
)
